package lec_1;

public class Odd_even {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a = 575873587 ;
		if (a>60) {// YES
			System.out.println("yes");
		}
		if (a%2==0) {// YES
			System.out.println("even");
		}
		else {// no
			System.out.println("odd");
		}
	}

}
